197	// 恰好等于上限（110 == 110）时也必须触线并撤销剩余量。
198	func TestRiskPartialBuyFillLossExactlyAtLimitTriggers(t *testing.T) {
199		e, bid := riskTradeSetup(t, 110) // 上限放宽到 110，成交后亏损恰好 110
200	
201		res, err := e.Fill(Trade{TradeID: 2, OrderID: bid, Symbol: "A", Side: Buy, Price: 20, Qty: 4})
202		if err != nil {
203			t.Fatalf("成交必须成功: %v", err)
204		}
205		if res.Status != StatusPartial || res.Filled != 4 || res.Remaining != 6 {
206			t.Fatalf("成交结果应为累计 4、剩余 6、部分成交: %+v", res)
207		}
208	
209		st := e.RiskStatus()
210		if !st.Restricted || st.Equity != 890 || st.Loss != 110 || st.LossLimit != 110 {
211			t.Fatalf("亏损恰好等于上限 110 时必须触线: %+v", st)
212		}
213		o, _ := e.Order(bid)
214		if o.Status != StatusCanceled || o.Filled != 4 || o.Remaining() != 0 {
215			t.Fatalf("剩余 6 股必须被风险保护撤销: %+v", o)
216		}
217		if e.Cash() != 820 || e.ReservedCash() != 0 || e.AvailableCash() != 820 || e.Position("A") != 14 {
218			t.Fatalf("成交入账且剩余占用释放后的资金持仓错误: cash=%d reserved=%d available=%d pos=%d",
219				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"))
220		}
221		rec := lastRiskRecord(t, e)
222		if rec.RiskTrigger != RiskTriggerTrade || rec.RiskRefSeq != 2 ||
223			rec.RiskLoss != 110 || rec.RiskLimit != 110 {
224			t.Fatalf("触线记录应关联成交 2 并固化亏损 110、上限 110: %+v", rec)
225		}
226		if countRiskRecords(e) != 1 {
227			t.Fatal("恰好达限只能产生一条触线记录")
228		}
229	}
230	
231	// TestRiskPartialBuyFillBelowLimitKeepsRemainderAndReserve 覆盖未触线路径：
232	// 成交后亏损仍低于上限时只完成部分成交，剩余买单与现金占用继续有效，
233	// 不产生触线或撤销记录。
234	func TestRiskPartialBuyFillBelowLimitKeepsRemainderAndReserve(t *testing.T) {
235		e, bid := riskTradeSetup(t, 100)
236	
237		// 仅成交 2 股 @20：现金 860、持仓 12，净值 860+60=920、亏损 80 < 100。
238		recsBefore := len(e.Records())
239		res, err := e.Fill(Trade{TradeID: 2, OrderID: bid, Symbol: "A", Side: Buy, Price: 20, Qty: 2})
240		if err != nil {
241			t.Fatalf("成交必须成功: %v", err)
242		}
243		if res != (FillResult{TradeID: 2, OrderID: bid, Price: 20, Qty: 2,
244			Filled: 2, Remaining: 8, Status: StatusPartial}) {
245			t.Fatalf("成交结果应为累计 2、剩余 8、部分成交: %+v", res)
246		}
247	
248		st := e.RiskStatus()
249		if st.Restricted || st.Equity != 920 || st.Loss != 80 {
250			t.Fatalf("亏损 80 未达上限 100，不应触线: %+v", st)
251		}
252	
253		// 订单仍为部分成交、剩余 8 股有效；剩余占用 8×20=160 继续保留。
254		o, _ := e.Order(bid)
255		if o.Status != StatusPartial || o.Filled != 2 || o.Qty != 10 || o.Remaining() != 8 || o.Reason != "" {
256			t.Fatalf("未触线时剩余买单必须继续有效: %+v", o)
257		}
258		if e.Cash() != 860 || e.ReservedCash() != 160 || e.AvailableCash() != 700 || e.Position("A") != 12 {
259			t.Fatalf("剩余 8 股的现金占用 160 必须继续保留: cash=%d reserved=%d available=%d pos=%d",
260				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"))
261		}
262	
263		// 只新增一条成交记录，不得有触线或撤销记录。
264		recs := e.Records()[recsBefore:]
265		if len(recs) != 1 || recs[0].Kind != RecordFilled {
266			t.Fatalf("未触线时只能新增一条成交记录，实际 %+v", recs)
267		}
268		if countRiskRecords(e) != 0 {
269			t.Fatal("未达上限不得产生触线记录")
270		}
271	
272		// 剩余部分仍可继续成交（占用有效）：再成交 8 股后订单全部成交。
273		res2, err := e.Fill(Trade{TradeID: 3, OrderID: bid, Symbol: "A", Side: Buy, Price: 20, Qty: 8})
274		if err != nil {
275			t.Fatalf("保留的剩余 8 股必须仍可成交: %v", err)
276		}
277		if res2.Status != StatusFilled || res2.Filled != 10 || res2.Remaining != 0 {
278			t.Fatalf("剩余 8 股全部成交后应为全部成交: %+v", res2)
279		}
280		if o2, _ := e.Order(bid); o2.Status != StatusFilled || e.ReservedCash() != 0 {
281			t.Fatalf("全部成交后占用应清零: order=%+v reserved=%d", o2, e.ReservedCash())
282		}
283	}
284	
285	// TestRiskTriggeredFillReplayReturnsFirstResultUnchanged 覆盖触线撤单后的幂等
286	// 重放：原样重提交已入账成交必须返回第一次结果（仍为部分成交、剩余 6），
287	// 现金、持仓、订单与记录均不再变化。
288	func TestRiskTriggeredFillReplayReturnsFirstResultUnchanged(t *testing.T) {
289		e, bid := riskTradeSetup(t, 100)
290	
291		tr := Trade{TradeID: 2, OrderID: bid, Symbol: "A", Side: Buy, Price: 20, Qty: 4}
292		res1, err := e.Fill(tr)
293		if err != nil {
294			t.Fatalf("首次成交必须成功: %v", err)
295		}
296	
297		recordsBefore := len(e.Records())
298		cashBefore, reservedBefore := e.Cash(), e.ReservedCash()
299		posBefore := e.Position("A")
300		orderBefore, _ := e.Order(bid)
301	
302		// 触线撤单后原样重放：返回第一次的结果（部分成交、剩余 6），
303		// 而不是订单当前的已撤销、剩余 0；两种结果不能相互覆盖。
304		res2, err := e.Fill(tr)
305		if err != nil {
306			t.Fatalf("已入账成交的原样重放必须成功返回原结果: %v", err)
307		}
308		if res1 != res2 {
309			t.Fatalf("重放必须原样返回第一次结果: first=%+v replay=%+v", res1, res2)
310		}
311		if res2.Status != StatusPartial || res2.Remaining != 6 {
312			t.Fatalf("重放结果必须保持首次的部分成交、剩余 6: %+v", res2)
313		}
314	
315		orderAfter, _ := e.Order(bid)
316		if orderAfter != orderBefore {
317			t.Fatalf("重放不得改变订单状态: before=%+v after=%+v", orderBefore, orderAfter)
318		}
319		if orderAfter.Status != StatusCanceled || orderAfter.Remaining() != 0 {
320			t.Fatalf("订单查询必须保持已撤销、有效剩余量 0: %+v", orderAfter)
321		}
322		if e.Cash() != cashBefore || e.ReservedCash() != reservedBefore || e.Position("A") != posBefore {
323			t.Fatalf("重放不得改变资金与持仓: cash=%d(before %d) reserved=%d(before %d) pos=%d(before %d)",
324				e.Cash(), cashBefore, e.ReservedCash(), reservedBefore, e.Position("A"), posBefore)
325		}
326		if len(e.Records()) != recordsBefore {
327			t.Fatalf("重放不得新增任何记录: before=%d after=%d", recordsBefore, len(e.Records()))
328		}
329		if countRiskRecords(e) != 1 {
330			t.Fatal("重放不得重复产生触线记录")
331		}
332	}
